function houseOfSign(signName, ascSignName) {
  const idx = SIGNS.indexOf(signName);
  const ascIdx = SIGNS.indexOf(ascSignName);
  return (((idx - ascIdx) % 12) + 12) % 12 + 1;
}

function findHouseIngresses(planetKey, targetHouse, ascSignName, startJD, windowDays = 730) {
  const houses = [];
  for (let t = 0; t <= windowDays; t++) {
    const sign = signOf(planetLongitude(planetKey, startJD + t)).sign;
    houses.push(houseOfSign(sign, ascSignName));
  }
  const ingresses = [];
  for (let t = 1; t <= windowDays; t++) {
    if (houses[t] === targetHouse && houses[t - 1] !== targetHouse) ingresses.push(t);
  }
  return ingresses;
}

function signInHouse(ascSignName, houseNum) {
  const ascIdx = SIGNS.indexOf(ascSignName);
  return SIGNS[(ascIdx + houseNum - 1) % 12];
}

