const CITY_LIST = ["Москва","Санкт-Петербург","Калининград","Новосибирск","Екатеринбург","Казань","Краснодар","Киев","Минск","Алматы"];

function geocodeCity(label) {
  if (!label) return null;
  const entry = CITY_DB[label.trim().toLowerCase()];
  if (!entry) return null;
  return { name: entry[0], lat: entry[1], lon: entry[2], tz: entry[3] };
}

// исторически точное смещение от UTC для конкретной даты и IANA-названия пояса (через Intl, без внешних библиотек)
function utcOffsetHours(tz, y, m, d, hh, mi) {
  const dtf = new Intl.DateTimeFormat("en-US", {
    timeZone: tz, hour12: false,
    year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", second: "2-digit",
  });
  let guessUTC = Date.UTC(y, m - 1, d, hh, mi, 0);
  const wantedUTC = Date.UTC(y, m - 1, d, hh, mi, 0);
  for (let i = 0; i < 5; i++) {
    const parts = dtf.formatToParts(new Date(guessUTC));
    const map = {};
    parts.forEach((p) => { map[p.type] = p.value; });
    const renderedUTC = Date.UTC(+map.year, +map.month - 1, +map.day, +map.hour, +map.minute, +map.second);
    const diff = wantedUTC - renderedUTC;
    if (diff === 0) break;
    guessUTC += diff;
  }
  return (wantedUTC - guessUTC) / 3600000;
}

/* ============ АСТРОНОМИЯ: Солнце, Луна, Асцендент (проверено отдельным расчётом) ============ */
function norm360(x) { x = x % 360; if (x < 0) x += 360; return x; }

function toJD(y, m, d, utcHour, utcMinute) {
  let yy = y, mm = m;
  const frac = (utcHour + utcMinute / 60) / 24;
  if (mm <= 2) { yy -= 1; mm += 12; }
  const A = Math.floor(yy / 100);
  const B = 2 - A + Math.floor(A / 4);
  const JD0 = Math.floor(365.25 * (yy + 4716)) + Math.floor(30.6001 * (mm + 1)) + d + B - 1524.5;
  return JD0 + frac;
}

function sunLongitude(JD) {
  const d = JD - 2451545.0;
  const L = norm360(280.460 + 0.9856474 * d);
  const g = (norm360(357.528 + 0.9856003 * d) * Math.PI) / 180;
  const lambda = L + 1.915 * Math.sin(g) + 0.02 * Math.sin(2 * g);
  return norm360(lambda);
}

function moonLongitude(JD) {
  const d = JD - 2451545.0;
  const Lm = norm360(218.316 + 13.176396 * d);
  const Mm = (norm360(134.963 + 13.064993 * d) * Math.PI) / 180;
  const D = (norm360(297.85 + 12.190749 * d) * Math.PI) / 180;
  let lambda = Lm + 6.289 * Math.sin(Mm);
  lambda += -1.274 * Math.sin(Mm - 2 * D);
  lambda += 0.658 * Math.sin(2 * D);
  return norm360(lambda);
}

function obliquity(JD) {
  const T = (JD - 2451545.0) / 36525;
  return 23.439291 - 0.0130042 * T;
}

function gst(JD) {
  const T = (JD - 2451545.0) / 36525;
  const g = 280.46061837 + 360.98564736629 * (JD - 2451545.0) + 0.000387933 * T * T - (T * T * T) / 38710000;
  return norm360(g);
}

function ascendant(JD, latDeg, lonDeg) {
  const lst = norm360(gst(JD) + lonDeg);
  const lstRad = (lst * Math.PI) / 180;
  const eps = (obliquity(JD) * Math.PI) / 180;
  const lat = (latDeg * Math.PI) / 180;
  const y = Math.cos(lstRad);
  const x = -(Math.sin(eps) * Math.tan(lat) + Math.cos(eps) * Math.sin(lstRad));
  return norm360((Math.atan2(y, x) * 180) / Math.PI);
}

function signOf(lon) {
  const l = norm360(lon);
  return { sign: SIGNS[Math.floor(l / 30)], deg: Math.floor(l % 30) };
}

/* ============ АСТРОНОМИЯ: Меркурий-Сатурн (гелиоцентрический Кеплер, проверено на периодах и элонгациях) ============ */
const ELEMENTS = {
  mercury: { a: 0.38709927, e: 0.20563593, L0: 252.2503235, Lr: 149472.67411175, pi0: 77.45779628, pir: 0.16047689 },
  venus:   { a: 0.72333566, e: 0.00677672, L0: 181.9790995, Lr: 58517.81538729, pi0: 131.60246718, pir: 0.00268329 },
  earth:   { a: 1.00000261, e: 0.01671123, L0: 100.46457166, Lr: 35999.37244981, pi0: 102.93768193, pir: 0.32327364 },
  mars:    { a: 1.52371034, e: 0.0933941, L0: 355.44656795, Lr: 19140.30268499, pi0: 336.05637041, pir: 0.44441088 },
  jupiter: { a: 5.202887, e: 0.04838624, L0: 34.39644051, Lr: 3034.74612775, pi0: 14.72847983, pir: 0.21252668 },
  saturn:  { a: 9.53667594, e: 0.05386179, L0: 49.95424423, Lr: 1222.49362201, pi0: 92.59887831, pir: -0.41897216 },
};

function keplerE(M, e) {
  let E = M;
  for (let i = 0; i < 40; i++) {
    const dE = (E - e * Math.sin(E) - M) / (1 - e * Math.cos(E));
    E -= dE;
    if (Math.abs(dE) < 1e-9) break;
  }
  return E;
}

function heliocentricXY(key, T) {
  const el = ELEMENTS[key];
  const L = norm360(el.L0 + el.Lr * T);
  const pi = norm360(el.pi0 + el.pir * T);
  const M = (norm360(L - pi) * Math.PI) / 180;
  const E = keplerE(M, el.e);
  const xOrb = el.a * (Math.cos(E) - el.e);
  const yOrb = el.a * Math.sqrt(1 - el.e * el.e) * Math.sin(E);
  const piRad = (pi * Math.PI) / 180;
  return {
    x: xOrb * Math.cos(piRad) - yOrb * Math.sin(piRad),
    y: xOrb * Math.sin(piRad) + yOrb * Math.cos(piRad),
  };
}

function planetLongitude(key, JD) {
  const T = (JD - 2451545.0) / 36525;
  const p = heliocentricXY(key, T);
  const e = heliocentricXY("earth", T);
  return norm360((Math.atan2(p.y - e.y, p.x - e.x) * 180) / Math.PI);
}

function isRetrograde(planetKey, JD) {
  const lonNow = planetLongitude(planetKey, JD);
  const lonNext = planetLongitude(planetKey, JD + 1);
  const diff = norm360(lonNext - lonNow);
  return diff > 180;
}

function northNodeLongitude(JD) {
  const t = (JD - 2451545.0) / 36525;
  const omega = 125.04452 - 1934.136261 * t + 0.0020708 * t * t + (t * t * t) / 450000;
  return norm360(omega);
}

/* ============ СБОРКА КАРТЫ ============ */
function computeChart(dateStr, timeStr, cityLabel) {
  const [y, m, d] = dateStr.split("-").map(Number);
  const hasTime = Boolean(timeStr);
  let hour = 12, minute = 0;
  if (hasTime) { const [hh, mm] = timeStr.split(":").map(Number); hour = hh; minute = mm; }

  const found = geocodeCity(cityLabel);
  const usedDefaultCity = !found;
  const city = found || { name: "Москва", lat: 55.7558, lon: 37.6173, tz: "Europe/Moscow" };
  const tzOffset = utcOffsetHours(city.tz, y, m, d, hour, minute);
  const utcHourFloat = hour - tzOffset;
  const utcHour = Math.floor(utcHourFloat);
  const utcMinute = minute + Math.round((utcHourFloat - utcHour) * 60);
  const jd = toJD(y, m, d, utcHour, utcMinute);

  const sun = signOf(sunLongitude(jd));
  const moon = signOf(moonLongitude(jd));
  const mercury = signOf(planetLongitude("mercury", jd));
  const venus = signOf(planetLongitude("venus", jd));
  const mars = signOf(planetLongitude("mars", jd));
  const jupiter = signOf(planetLongitude("jupiter", jd));
  const saturn = signOf(planetLongitude("saturn", jd));
  const rising = hasTime ? signOf(ascendant(jd, city.lat, city.lon)) : null;
  const northNodeLon = northNodeLongitude(jd);
  const northNode = signOf(northNodeLon);
  const southNode = signOf(northNodeLon + 180);

  return { sun, moon, mercury, venus, mars, jupiter, saturn, rising, northNode, southNode, northNodeLon, birthJD: jd, hasTime, city, usedDefaultCity };
}

/* ============ ПРОГНОЗ: поиск дат, когда транзитная планета образует аспект к натальной точке ============ */
function angDiff(a, b) { let d = Math.abs(norm360(a - b)); if (d > 180) d = 360 - d; return d; }

function jdToYMD(jd) {
  let Z = Math.floor(jd + 0.5), A2 = Z;
  if (Z >= 2299161) { const al = Math.floor((Z - 1867216.25) / 36524.25); A2 = Z + 1 + al - Math.floor(al / 4); }
  const B2 = A2 + 1524, C2 = Math.floor((B2 - 122.1) / 365.25), D2 = Math.floor(365.25 * C2), E2 = Math.floor((B2 - D2) / 30.6001);
  const day = Math.floor(B2 - D2 - Math.floor(30.6001 * E2));
  const month = E2 < 14 ? E2 - 1 : E2 - 13;
  const year = month > 2 ? C2 - 4716 : C2 - 4715;
  return { year, month, day };
}

function yearWord(n) {
  n = Math.abs(n) % 100;
  const n1 = n % 10;
  if (n >= 11 && n <= 14) return "лет";
  if (n1 === 1) return "год";
  if (n1 >= 2 && n1 <= 4) return "года";
  return "лет";
}

function jdToDateLabel(jd) {
  const { year, month, day } = jdToYMD(jd);
  const months = ["янв","фев","мар","апр","мая","июн","июл","авг","сен","окт","ноя","дек"];
  return `${day} ${months[month - 1]} ${year}`;
}

function findTransitHits(natalLon, planetKey, startJD, windowDays, threshold = 2) {
  const daily = [];
  for (let t = 0; t <= windowDays; t++) daily.push(angDiff(planetLongitude(planetKey, startJD + t), natalLon));
  const hits = [];
  for (const asp of ASPECT_LIST) {
    let inCluster = false, minOrb = Infinity, minDay = 0;
    for (let t = 0; t <= windowDays; t++) {
      const orb = Math.abs(daily[t] - asp.angle);
      if (orb < threshold) {
        if (!inCluster) { inCluster = true; minOrb = orb; minDay = t; }
        else if (orb < minOrb) { minOrb = orb; minDay = t; }
      } else if (inCluster) {
        hits.push({ dayOffset: minDay, aspectKey: asp.key, aspectName: asp.name });
        inCluster = false;
      }
    }
    if (inCluster) hits.push({ dayOffset: minDay, aspectKey: asp.key, aspectName: asp.name });
  }
  hits.sort((a, b) => a.dayOffset - b.dayOffset);
  return hits.map((h) => ({ ...h, dateLabel: jdToDateLabel(startJD + h.dayOffset) }));
}

function computeForecast(chart, windowDays = 730) {
  const now = new Date();
  const nowJD = toJD(
    now.getUTCFullYear(), now.getUTCMonth() + 1, now.getUTCDate(),
    now.getUTCHours(), now.getUTCMinutes()
  );
  const natalPoints = { sun: chart.sun, moon: chart.moon };
  const results = [];
  for (const planetKey of ["jupiter", "saturn"]) {
    for (const pointKey of ["sun", "moon"]) {
      const natalDeg = SIGNS.indexOf(natalPoints[pointKey].sign) * 30 + natalPoints[pointKey].deg;
      const hits = findTransitHits(natalDeg, planetKey, nowJD, windowDays);
      hits.forEach((h) => {
        const transitSign = signOf(planetLongitude(planetKey, nowJD + h.dayOffset)).sign;
        results.push({ ...h, planetKey, pointKey, transitSign });
      });
    }
  }
  results.sort((a, b) => a.dayOffset - b.dayOffset);
  return results;
}

